  const pct=v=>(v*100).toFixed(1)+'%',num=v=>v==null?'未定义':v.toFixed(4);
  let snapshots=D.snapshots.map(x=>({...x,state:C.normalize(x.state)}));
  let graph=snapshots[snapshots.length-1].state,selected='ANALYSIS-MEMBER-PROP',mode='focus',view='graph',search='',zoom=1,box={x:0,y:0,w:1000,h:600},originalBox={...box},drag=null;
  const titles={graph:['研究图谱','证据变了，哪些结论需要重新检查？'],changes:['变更审阅','保留人的判断、修订理由与前后差异。'],results:['实验与证据','两个真实分析案例，数值与解释分开核查。'],policy:['任务策略','从人的纠正中形成方法，也记录方法没能发现的错误。'],about:['项目与开源','让科研变化有依据、有边界、有记录。']};
  function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
