  function setSnapshot(index){graph=snapshots[index].state;if(!graph.nodes.some(n=>n.id===selected))selected=graph.nodes[0]?.id;search='';$('node-search').value='';renderGraph();renderDetails();$('version-label').textContent=snapshots[index].label;$('nav-node-count').textContent=graph.nodes.length;}
