      g.append(svgEl('text',{x:p.x+13,y:p.y+79,'font-size':7.5,'class':'node-caption'},n.id.length>29?n.id.slice(0,28)+'…':n.id));g.append(svgEl('title',{},n.text));
      g.addEventListener('click',()=>{if(!drag?.moved)chooseNode(n.id);});g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseNode(n.id);}});svg.append(g);
